// Only callers that know the demo token may trigger generation over HTTP:
//   curl -X POST http://localhost:5678/webhook/staqly-demo-generate -H 'X-Demo-Token: <token>'
// Paste the token printed by integrations/n8n/setup-demo.sh below. While it is
// empty the HTTP trigger is disabled (the manual trigger always works).
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto (the example compose sets it).
const DEMO_TOKEN = '';
if (!DEMO_TOKEN) {
  throw new Error('Demo token not configured: paste the X-Demo-Token printed by setup-demo.sh into DEMO_TOKEN in the "Check demo token" node');
}
const crypto = require('crypto');
const digest = (s) => crypto.createHash('sha256').update(String(s)).digest();
for (const item of $input.all()) {
  const given = (item.json.headers || {})['x-demo-token'] || '';
  if (!crypto.timingSafeEqual(digest(given), digest(DEMO_TOKEN))) {
    throw new Error('Invalid or missing X-Demo-Token header');
  }
}
return $input.all();

// Find or create the demo channel on your own automation: create it only when no channel of that name exists,
// so running the generator again never adds a second channel.
const cfg = $('Config').first().json;
const headers = { Authorization: 'Bearer ' + cfg.apiToken };
const list = await this.helpers.httpRequest({ method: 'GET', url: cfg.apiBaseUrl + '/v1/channels', headers, json: true });
const found = (list.data || []).some((c) => c.name === cfg.channel && c.provider === 'custom');
if (!found) {
  await this.helpers.httpRequest({ method: 'POST', url: cfg.apiBaseUrl + '/v1/channels', headers, json: true,
    body: { provider: 'custom', name: cfg.channel, fields: { delivery: 'agent' } } });
}
return [{ json: { channel: cfg.channel, created: !found } }];

// Picks the demo channel's id out of the channel list and carries the config along.
const cfg = $('Config').item.json;
const list = ($input.first().json.data || []);
const channel = list.find((c) => c.name === cfg.channel && c.provider === 'custom');
if (!channel) throw new Error('Channel "' + cfg.channel + '" not found: run integrations/n8n/setup-demo.sh or create it in Channels');
return [{ json: { apiBaseUrl: cfg.apiBaseUrl, collection: cfg.collection, channelId: channel.id } }];

// Mock AI generator: stands in for prompt generation + image generation. It
// produces a caption and a small PNG, with no external accounts. Replace this
// node with real generation steps.
const IMAGES = ["", "", "", ""];
const SUBJECTS = ['golden hour rooftop portrait', 'neon city night walk', 'cozy cafe morning', 'beach sunset, film grain', 'minimal studio portrait'];
const out = [];
for (const [i, item] of $input.all().entries()) {
  const req = item.json;
  const seed = Math.floor(Math.random() * 1e6);
  const subject = SUBJECTS[seed % SUBJECTS.length];
  const prompt = 'photorealistic AI avatar, ' + subject + ', 35mm, soft light';
  const caption = 'New day, new vibe: ' + subject + ' #aiavatar';
  out.push({
    json: {
      request: req,
      post: {
        title: 'Avatar post: ' + subject,
        content: 'Avatar post: ' + subject + '\n' + caption,
        source: 'n8n:instagram-avatar-demo',
        external_ref: 'gen-' + seed,
        tags: ['avatar', 'demo'],
        metadata: { prompt, seed, model: 'mock-higgsfield-v1', inspiration: 'mock-trend-scan' },
      },
    },
    binary: { data: { data: IMAGES[seed % IMAGES.length], mimeType: 'image/png', fileName: 'avatar-' + seed + '.png' } },
    pairedItem: i,
  });
}
return out;

// Verifies the staqly signature, rejects stale and replayed events, then
// parses the event. Fails closed: without CONFIG.webhookSecret nothing is
// processed. Paste the secret printed by integrations/n8n/setup-demo.sh
// (or shown in Staqly → Webhooks). Verification needs the 'crypto' builtin:
// set NODE_FUNCTION_ALLOW_BUILTIN=crypto on n8n (the example compose does).
const CONFIG = {
  apiBaseUrl: 'http://api:3333',   // n8n on the host: http://localhost:3333
  apiToken: '',                    // Staqly's access token (local: `staqly serve token`) or a cloud API key
  webhookSecret: '',
  toleranceSeconds: 300,
  dedupeSize: 500,                 // how many recent X-Staqly-Event-Id values to remember
};
if (!CONFIG.webhookSecret) {
  throw new Error('Webhook secret not configured: paste the webhook secret from setup-demo.sh into CONFIG.webhookSecret in the "Verify & parse" node');
}
const crypto = require('crypto');
// Deliveries are at-least-once: remember recent event IDs (persisted for
// active workflows) and drop repeats.
const state = $getWorkflowStaticData('global');
if (!Array.isArray(state.staqlyEventIds)) state.staqlyEventIds = [];
const seen = state.staqlyEventIds;
const out = [];
for (const [i, item] of $input.all().entries()) {
  const raw = item.binary && item.binary.data
    ? await this.helpers.getBinaryDataBuffer(i, 'data')
    : Buffer.from(JSON.stringify(item.json.body));
  const h = item.json.headers || {};
  const ts = String(h['x-staqly-timestamp'] || '');
  if (!/^\d+$/.test(ts)) throw new Error('Missing or invalid X-Staqly-Timestamp');
  if (Math.abs(Math.floor(Date.now() / 1000) - Number(ts)) > CONFIG.toleranceSeconds) {
    throw new Error('Stale Staqly webhook: timestamp outside the tolerance window');
  }
  const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', CONFIG.webhookSecret).update(ts + '.').update(raw).digest('hex'));
  const given = Buffer.from(String(h['x-staqly-signature'] || ''));
  if (given.length !== expected.length || !crypto.timingSafeEqual(given, expected)) {
    throw new Error('Invalid Staqly signature');
  }
  const event = JSON.parse(raw.toString('utf8'));
  const eventId = String(h['x-staqly-event-id'] || event.id || '');
  if (eventId) {
    if (seen.includes(eventId)) continue; // duplicate delivery: already handled
    seen.push(eventId);
    if (seen.length > CONFIG.dedupeSize) seen.splice(0, seen.length - CONFIG.dedupeSize);
  }
  const post = (event.data && event.data.post) || {};
  const channel = (event.data && event.data.channel) || {};
  const target = (event.data && event.data.target) || {};
  out.push({ json: { config: CONFIG, verified: true, event, post, channel, target }, pairedItem: i });
}
return out;

// Mock Instagram publisher: pretends to post the picture + caption of this
// target. Replace with the real Instagram Graph API call in production. The
// text to publish is the target's own (data.target.content): the post's text,
// or what the composer gave this channel.
return $input.all().map((item, i) => {
  const src = $('Verify & parse').itemMatching(i).json;
  const postId = '17' + String(Math.abs([...src.post.id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) | 0, 7))).padStart(14, '0');
  return {
    json: { instagram_post_id: postId, instagram_url: 'https://instagram.example/p/' + postId, caption: src.target.content,
            media: (src.post.media_items || []).map((m) => m.url), published_at: new Date().toISOString() },
    pairedItem: i,
  };
});

// post.published / post.failed: where it ended up, per channel. Hook your
// own logging, a team chat message or a ticket here.
return $input.all().map((item, i) => {
  const { event, post } = item.json;
  return { json: {
    post_id: post.id, status: post.status, type: event.type,
    links: (post.targets || []).filter((t) => t.external_url).map((t) => ({ channel: t.channel_name, url: t.external_url })),
    errors: (post.targets || []).filter((t) => t.error).map((t) => ({ channel: t.channel_name, error: t.error })),
  }, pairedItem: i };
});
